package co.edu.cinematch.security;
import io.jsonwebtoken.Claims; import io.jsonwebtoken.JwtException; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtFilter(JwtService jwt){this.jwt=jwt;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Claims x=jwt.leer(h.substring(7));var a=new UsernamePasswordAuthenticationToken(x.getSubject(),null,java.util.List.of(new SimpleGrantedAuthority("ROLE_"+x.get("rol",String.class))));SecurityContextHolder.getContext().setAuthentication(a);}catch(JwtException ignored){} c.doFilter(r,s);}}
